SELECT
    mbbcjd.*
FROM mes_building_bo_chu_job_directory mbbcjd
WHERE mbbcjd.bool_delete_enum = 0 AND mbbcjd.job_type = 1

    AND DATE(mbbcjd.create_time) >= #{startDate}


    AND DATE(mbbcjd.create_time) <= #{endDate}


    AND EXISTS(SELECT 1 FROM mes_building_bo_chu_nesting_result mbbcnr WHERE mbbcnr.bool_delete_enum = 0 AND mbbcnr.job_id = mbbcjd.job_id AND mbbcnr.cut_send_status = #{cutSendStatus})


    AND mbbcjd.project_id = #{projectId}


    AND mbbcjd.workshop_id IN
    
        #{i}
    


    AND EXISTS(select 1 from mes_building_task_need_machine_part_scheduling mbtnmps WHERE mbtnmps.bool_delete_enum = 0 and mbtnmps.nesting_job_id = mbbcjd.job_id and mbtnmps.monomer_id = #{monomerId})


    AND EXISTS(select 1 from mes_building_task_need_machine_part_scheduling mbtnmps WHERE mbtnmps.bool_delete_enum = 0 and mbtnmps.nesting_job_id = mbbcjd.job_id and mbtnmps.area_id = #{areaId})

    OR (mbbcjd.job_type = 0 AND mbbcjd.bool_delete_enum = 0
    
        AND (mbbcjd.project_id IS NULL OR mbbcjd.project_id = #{projectId})
    
    
        AND mbbcjd.workshop_id IN
        
            #{i}
        
    
    )
